using System.Buffers.Binary;

using Aow.Formats;
using Aow.Formats.Json;

using Aow.Formats.Original;
using Aow.Rtl;

namespace Aow.Convert;

/// <summary>
/// The generated synthetic cases (own-formats.md 1.3 and the 9.7-0 fixture plan), counted
/// separately from the corpus. Each case is generated by code or derived from the installed game
/// files and states its expected result. A case whose input is unavailable fails with a reason.
/// </summary>
public static partial class Fixtures
{
    public sealed record Summary(int Cases, int Failed, int OwnDocuments, int OwnFailed);

    public sealed record Case(string Group, string Name, Func<Outcome> Run)
    {
        /// <summary>Whether the case reads the installed game. The others are generated by code alone.</summary>
        public bool UsesGame => !s_gameFree.Contains(Group + "/" + Name);
    }

    private static readonly HashSet<string> s_gameFree = new(StringComparer.Ordinal)
    {
        "lists/empty hero list", "lists/empty item list", "unknown/unknown stored class id", "unknown/unknown property id",
        "strings/long prefix for a short string", "strings/all 256 code page bytes",
        "layout/long table entries and a gap after a Boolean", "layout/a noncanonical table order",
        "layout/an edit invalidates the layout and export rebuilds it", "layout/--exact-layout refuses a stale layout",
        "layout/a part that does not fit is an error, not a cleanup", "gzip/bounded gzip",
        "gzip/a damaged own document never falls back to binary", "diagnostics/duplicate JSON member with both locations",
        "diagnostics/a binary error gives the offset and the profile", "diagnostics/trailing commas and comments fail",
        "diagnostics/a newer version fails with both numbers", "diagnostics/an older version fails and asks for a new conversion",
    };

    /// <summary>A case result. OwnDocuments counts the own documents the case checked for G-own.</summary>
    public sealed record Outcome(bool Matched, string Detail, int OwnDocuments = 0);

    private static Outcome Pass(string detail, int own = 0) => new(true, detail, own);

    private static Outcome Fail(string detail) => new(false, detail);

    public static Summary Run(TextWriter errors)
    {
        int cases = 0, failed = 0, own = 0, ownFailed = 0;
        foreach (var c in All())
        {
            cases++;
            Outcome outcome;
            try
            {
                outcome = c.Run();
            }
            catch (System.Exception error) when (error is ConversionException or IOException or InvalidOperationException or InvalidCastException or KeyNotFoundException or NullReferenceException)
            {
                outcome = Fail("unexpected " + error.GetType().Name + ": " + error.Message);
            }
            own += outcome.OwnDocuments;
            if (!outcome.Matched)
            {
                failed++;
                if (outcome.OwnDocuments > 0) ownFailed += outcome.OwnDocuments;
                errors.WriteLine($"fixture {c.Group}/{c.Name}: {outcome.Detail}");
            }
        }
        return new Summary(cases, failed, own, ownFailed);
    }

    // ---- Inputs ------------------------------------------------------------------------------

    private static byte[] Game(string relative)
    {
        string path = Path.Combine(Checker.GameRoot, relative.Replace('/', Path.DirectorySeparatorChar));
        if (!File.Exists(path)) throw new IOException($"Game file {relative} is unavailable under {Checker.GameRoot}.");
        return File.ReadAllBytes(path);
    }

    private const string Map = "Scenario/Custom/Mountain Clash.hsm";
    private const string Campaign = "Scenario/Campaign/Keepers.CAM";
    private const string ScenarioSet = "Release/Release.hss";
    private const string HeroList = "Release/High Level.ahl";
    private const string Tutorial = "Scenario/Custom/Tutorial.hsm";

    private static FileProfile FindProfile(string name) => FileProfile.Find(name)!;

    private static byte[]? s_mapText;

    /// <summary>A fresh copy of the imported Mountain Clash document. The import runs once per process.</summary>
    private static JsonObject MapDocument() => Parse(MapText());

    /// <summary>The canonical own text of Mountain Clash. A parsed copy has no row layout marks, so
    /// canonical text comes from the import.</summary>
    private static byte[] MapText() => s_mapText ??= GameFiles.Write(Import(Game(Map), "world-hsm", "map"));

    private static JsonObject Import(byte[] file, string profile, string kind) => GameFiles.Import(file, FindProfile(profile), kind).Document;

    private static JsonObject Parse(byte[] own) => GameFiles.Read(own).Document;

    private static JsonObject Copy(JsonObject document) => Parse(GameFiles.Write(document));

    private static JsonObject Object(JsonValue? value) => value as JsonObject ?? throw new InvalidOperationException("Not an object.");

    private static JsonArray Arr(JsonValue? value) => value as JsonArray ?? throw new InvalidOperationException("Not an array.");

    private static JsonObject Root(JsonObject document) => Object(document["root"]);

    private static void Set(JsonObject objectValue, string name, JsonValue value)
    {
        var member = objectValue.Find(name);
        if (member is null) objectValue.Add(name, value);
        else member.Value = value;
    }

    private static JsonObject Envelope(string kind, string profile, JsonObject root, string compression = "none") =>
        new JsonObject()
            .Add("$format", new JsonString(OwnFormat.FormatName))
            .Add("$version", new JsonInteger(OwnFormat.CurrentVersion))
            .Add("$kind", new JsonString(kind))
            .Add("$container", new JsonObject().Add("profile", new JsonString(profile)).Add("compression", new JsonString(compression)))
            .Add("root", root);

    // ---- Checks ------------------------------------------------------------------------------

    /// <summary>G1 and G2 over one original file, and G-own over its document.</summary>
    private static Outcome RoundTrip(byte[] file, string profile, string kind, Func<JsonObject, string?>? inspect = null)
    {
        var p = FindProfile(profile);
        var imported = GameFiles.Import(file, p, kind);
        var text = GameFiles.Write(imported.Document);
        var exported = GameFiles.Export(GameFiles.Read(text).Document);
        if (!p.Comparable(file, FormatLimits.Default).AsSpan().SequenceEqual(p.Comparable(exported.Bytes, FormatLimits.Default)))
            return Fail("G1 differs");
        var again = GameFiles.Write(GameFiles.Import(exported.Bytes, p, kind).Document);
        if (!again.AsSpan().SequenceEqual(text)) return Fail("G2 differs");
        var n1 = GameFiles.Normalize(text).Bytes;
        if (!GameFiles.Normalize(n1).Bytes.AsSpan().SequenceEqual(n1)) return Fail("G-own differs");
        if (inspect?.Invoke(imported.Document) is string problem) return Fail(problem);
        return Pass($"G1, G2 and G-own hold, {imported.Counts.Parts} layout parts", 1);
    }

    /// <summary>G2 and G-own for an own document: the import of its export is its normal form.</summary>
    private static Outcome OwnRoundTrip(JsonObject document, Func<JsonObject, byte[], string?>? inspect = null)
    {
        var (profile, kind, _, _) = GameFiles.Envelope(document, null);
        var exported = GameFiles.Export(document);
        var normal = GameFiles.Import(exported.Bytes, profile, kind).Document;
        var text = GameFiles.Write(normal);
        var exportedAgain = GameFiles.Export(Parse(text));
        if (!profile.Comparable(exportedAgain.Bytes, FormatLimits.Default).AsSpan().SequenceEqual(profile.Comparable(exported.Bytes, FormatLimits.Default)))
            return Fail("G1 differs for the exported original");
        if (!GameFiles.Write(GameFiles.Import(exportedAgain.Bytes, profile, kind).Document).AsSpan().SequenceEqual(text))
            return Fail("G2 differs");
        var n1 = GameFiles.Normalize(GameFiles.Write(document)).Bytes;
        if (!n1.AsSpan().SequenceEqual(text)) return Fail("N(D) differs from the import of the export");
        if (!GameFiles.Normalize(n1).Bytes.AsSpan().SequenceEqual(n1)) return Fail("G-own differs");
        if (inspect?.Invoke(normal, exported.Bytes) is string problem) return Fail(problem);
        return Pass("G2 and G-own hold", 1);
    }

    private static Outcome Expect(string code, Action action, Func<FormatDiagnostic, string?>? inspect = null)
    {
        try
        {
            action();
        }
        catch (ConversionException error)
        {
            if (error.Diagnostic.Code != code) return Fail($"expected {code}, got {error.Diagnostic}");
            if (inspect?.Invoke(error.Diagnostic) is string problem) return Fail(problem + ": " + error.Diagnostic);
            return Pass(error.Diagnostic.ToString());
        }
        return Fail($"expected {code}, the conversion succeeded");
    }

    private static string? Located(FormatDiagnostic d) =>
        d.Span.IsKnown || d.Offset is not null ? null : "the diagnostic has no location";

    // ---- Binary helpers ------------------------------------------------------------------------

    private static byte[] Payload(byte[] cfs) => cfs[4] == 0 ? cfs[5..] : Cfs.Inflate(cfs.AsSpan(5), 1L << 30, m => new InvalidDataException(m));

    private static byte[] Concat(params byte[][] parts)
    {
        var b = new ByteBuffer();
        foreach (var p in parts) b.Bytes(p);
        return b.ToArray();
    }

    private static byte[] I32(int v)
    {
        var b = new byte[4];
        BinaryPrimitives.WriteInt32LittleEndian(b, v);
        return b;
    }

    /// <summary>A written hero list: the outer table, then a THeroLibrary table and data.</summary>
    private static byte[] HeroListImage(byte[] table, byte[] data) => Concat([1, 0, 0], table, data);

    private static string ShortString(string s) => System.Convert.ToHexStringLower(Concat([(byte)s.Length], Cp1252.Encode(s)));
}
